"""Report actual coverage, unresolved needs and data readiness for demo scenarios."""
from collections import Counter
import json
import re
from scripts.build_dataset import ROOT,RAW,OUT,NOW,load,save,distance
from scripts.enrich_extended import rows

def main():
    coverage=load(OUT/'checklist_coverage.json',[]);summary=load(OUT/'summary.json',{});extra=load(OUT/'extended_enrichment_summary.json',{});transit=load(OUT/'transit_summary.json',{});event_summary=load(OUT/'events_enrichment_summary.json',{})
    pois=rows('pois.jsonl');events=rows('events.jsonl');trips=rows('transit_routes.jsonl');legs=rows('transit_legs.jsonl')
    attempts=load(RAW/'extended_index.json',[]);missing=[r for r in coverage if r['known_count']==0];partial=[r for r in coverage if r['status']=='partial']
    save(OUT/'collection_backlog.json',{'created_at':NOW,'scope':'110 checklist fields in sections 1-9; null is unknown; field presence is not universal completeness','unavailable_fields':missing,'partial_fields':partial,'source_failures':[r for r in attempts if r.get('error')],'external_dependencies':[{'need':'Current city-wide GTFS/timetable','reason':'CTS public pages inspected; no current machine-readable city-wide feed obtained. 2GIS supplies sampled journey estimates, not all schedules.'},{'need':'Outlet availability, measured noise and verified accessible paths','reason':'Require explicit venue statements, suitable review evidence or field verification; category alone is insufficient.'},{'need':'Crowding and popularity trend','reason':'Require permitted live occupancy data and repeated historical observations.'},{'need':'Independent factual verification','reason':'Downloading a page or reading a publisher status does not independently confirm opening, cancellation, hazards or accessibility.'}]})
    filters=[('coffee','Кофейня рядом с MEGA Silk Way','food_drink',['opening_hours']),('quiet','Тихое кафе с розеткой','food_drink',['quiet_place','power_outlets','wifi_available']),('child','Прогулка с ребёнком','children',['playground']),('airport','Достопримечательности за 2 часа до вылета','sightseeing',['suggested_visit_duration_min']),('night','Поздние заведения','nightlife',['opening_hours'])]
    scenarios=[]
    for sid,text,category,fields in filters:
        candidates=[p for p in pois if p['category']==category and p.get('operational_status') not in ('temporarily_closed','permanently_closed') and all(p.get(f) is not None for f in fields)]
        confirmed=[p for p in candidates if all(p.get(f) is True for f in fields if f in ('quiet_place','power_outlets','wifi_available','playground'))]
        if sid=='coffee':confirmed=[p for p in confirmed if distance((51.089,71.407),(p['latitude'],p['longitude']))<=2000 and re.search('cafe|coffee|кофейн|кафе',p['subcategory'],re.I)]
        if sid=='night':
            def has_late_hours(p):
                if p.get('is_24_7') is True:return True
                weekly=p.get('opening_hours_by_day') or {}
                return any(end>='23:00' or end<start for intervals in weekly.values() if intervals for start,end in intervals)
            confirmed=[p for p in confirmed if has_late_hours(p)]
        scenarios.append({'scenario_id':sid,'request':text,'required_fields':fields,'candidate_count':len(confirmed),'candidate_count_scope':'Fields and category only; coffee additionally within 2km of MEGA, night additionally has late weekly hours. Airport time budget is not checked.','example_poi_ids':[p['poi_id'] for p in confirmed[:5]],'data_ready':bool(confirmed) and sid!='airport','missing_runtime_context':['flight time, boarding/security buffer and fresh travel time from selected POI'] if sid=='airport' else [],'application_end_to_end_tested':False,'limitations':'Source claims only. Router, weather refresh and app recommendation behaviour must be tested in the actual application.'})
    save(OUT/'demo_scenarios.json',scenarios)
    query_specs=[('food_drink','Кофейня рядом','opening_hours'),('culture','Музей рядом','adult_ticket_price'),('nature','Прогулка в парке','indoor_outdoor'),('children','С ребёнком','playground'),('quiet_spaces','Место для работы','wifi_available'),('nightlife','Куда сходить вечером','opening_hours'),('entertainment','Развлечения','age_restrictions'),('sightseeing','Что посмотреть','short_description')]
    tests=[]
    for place,lat,lon in [('MEGA Silk Way',51.089,71.407),('Байтерек',51.1282882,71.4304546),('Астана Опера',51.1354512,71.410753),('Ailand',51.1481229,71.4167693),('аэропорт',51.0276,71.4668)]:
        for category,text,field in query_specs:
            tests.append({'query_id':f'q{len(tests)+1:02d}','text':text+' — '+place,'latitude':lat,'longitude':lon,'category':category,'expected_behaviour':['Use walking graph or provider route, never label straight-line distance as walking distance','Unknown '+field+' must stay unknown','Exclude explicitly closed places','Show source and collection time'],'application_test_status':'not_run_application_not_in_this_dataset_project'})
    save(OUT/'demo_test_queries.json',tests)
    tripids={t['trip_id'] for t in trips};poiids={p['poi_id'] for p in pois}
    checks={'transit_ids_unique':len(tripids)==len(trips),'transit_legs_reference_existing_trip':all(l['trip_id'] in tripids for l in legs),'transit_durations_positive':all(t.get('transit_duration_min',0)>0 for t in trips),'transit_anchors_in_study_area':all(all(50.98<=p['lat']<=51.34 and 71.18<=p['lon']<=71.75 for p in (t['source_point'],t['target_point'])) for t in trips),'events_reference_known_venues':all(not e.get('venue_poi_id') or e['venue_poi_id'] in poiids for e in events),'imported_events_have_astana_locality':all(e.get('event_location') for e in events if e.get('pipeline_module')=='extended_v1'),'all_new_facts_have_evidence':all(f.get('evidence_text') and f.get('source_url') for f in rows('facts.jsonl') if f.get('pipeline_module')=='extended_v1'),'outlet_claims_have_source_scope':all(p.get('power_outlets_scope') or p.get('raw_osm_tags',{}).get('socket') for p in pois if p.get('power_outlets') is not None)}
    save(OUT/'extended_validation_report.json',{'validated_at':NOW,'checks':checks,'all_passed':all(checks.values())})
    if not all(checks.values()):raise AssertionError(checks)
    wx=load(OUT/'weather_alerts.json',{});known=summary.get('field_coverage',{})
    lines=['# Дополнение датасета: фактический результат','',f'Обновлено: {NOW}. Объектов: {len(pois):,}. Новых фактов об объектах: {extra.get("facts_added",0):,}.','', '## Что добавлено','',f'- Афиша: {len(events):,} записей/сеансов, из них {event_summary.get("upcoming_or_ongoing",0):,} с неистёкшим периодом по источнику. Цены: {sum(e.get("event_price") is not None for e in events)}; возраст: {sum(e.get("event_age_group") is not None for e in events)}; опубликованный статус: {sum(e.get("event_status") is not None for e in events)}.',f'- Транспорт: {len(trips)} вариантов для {transit.get("pair_count",0)} пар демонстрационных точек; ходьба, ожидание, номера линий, остановки и геометрия участков. Полного расписания/GTFS нет.',f'- Погода: {len(wx.get("items",[]))} официальных предупреждений Казгидромета по Астане. Это снимок с опубликованными сроками действия.',f'- Цены взрослого билета: {known.get("adult_ticket_price",0)} объектов; детского: {known.get("child_ticket_price",0)}. Включены Ailand и Музей Сингулярности alem.ai.',f'- Метаданные лицензированных фотографий: {summary.get("poi_with_licensed_photo_metadata",0)} объектов. Изображения не скачивались; содержимое требует визуальной проверки.',f'- Изучено успешных страниц: {sum(bool(x.get("path")) for x in attempts)}; ошибок источников: {sum(bool(x.get("error")) for x in attempts)}. Ответы и ошибки сохранены.','', '## Исправления актуальности','', '- Старый музей энергии будущего NUR ALEM закрыт для посещения с декабря 2024 года по официальному сообщению. Здание не закрыто: там находится alem.ai. Новый Музей Сингулярности имеет отдельную карточку; старые часы не считаются действующими.', '- Филиал Vo Dvore на Куйши Дина отмечен временно закрытым; декабрь 2026 — опубликованный ориентир открытия, не гарантия.', '- Ограничения оранжереи относятся к оранжерее, а не ко всей территории ботанического сада. В том числе запрещены коляски и домашние животные.', '- Возможность бронирования сохранена в reservation_available; она не означает, что бронирование обязательно.', '- Одно свидетельство о тишине — субъективный отзыв, выбранный самим заведением, не объективное измерение. См. quiet_place_scope.','', '## Что остаётся неизвестным','', '- Розетки отмечены только у двух филиалов по редакционным публикациям, без проверки на месте. Измеренный уровень шума, текущая загруженность, динамика популярности и подтверждённые безбарьерные маршруты не получены.', '- Нет текущего полного расписания городского транспорта. Сохранённые расчёты для отдельных пар точек не заменяют расписание и обновление маршрута при запросе.', '- Большинство POI не имеет подробной независимой проверки. Описания, статусы и цены — сведения источников с датой получения.', '- Поля verified_at и hours_verified_at не заполняются датой скачивания страницы. Проверки OSM-конtributors сохранены отдельно в source_hours_checked_at.', '- Не все билетные цены и удобства применимы ко всем категориям POI: проценты покрытия в DATA_REPORT.md рассчитаны по всей базе.', '', '## Демонстрация','',f'Подготовлены {len(tests)} тестовых запросов и {len(scenarios)} сценариев в JSON. Это спецификации для проверки приложения; прохождение RAG/чат-интерфейса не заявляется.','', '| Сценарий | Подходящих карточек по заполненным полям |','|---|---:|']
    for x in scenarios:lines.append(f'| {x["request"]} | {x["candidate_count"]} |')
    lines+=['','Для кофе учтён радиус 2 км от MEGA и подкатегория кафе/кофейни; для ночных заведений — поздние часы хотя бы в один день недели. Для сценария с вылетом показаны только туристические карточки с оценкой длительности визита: бюджет двух часов, время рейса и запас на посадку ещё нужно проверить в приложении.']
    lines+=['','Все незаполненные и частичные пункты MD с попытками сбора: `data/processed/collection_backlog.json`. Точное покрытие: `DATA_REPORT.md`. Происхождение и оговорки каждого добавленного факта: `facts.jsonl`.','']
    (ROOT/'ENRICHMENT_REPORT.md').write_text('\n'.join(lines),encoding='utf-8')
    print(json.dumps({'unavailable_field_rows':len(missing),'partial_field_rows':len(partial),'test_queries':len(tests),'demo_scenarios':len(scenarios),'extended_checks_passed':len(checks)},ensure_ascii=False))

if __name__=='__main__':main()
